from collections import deque


class ConnectGame:
    def __init__(self, board):
        # Parse the board into a 2D grid of cells.
        # Each line is a row of the rhombus; cells are separated by spaces and
        # the leading indentation encodes the rhombus shear. Splitting on
        # whitespace drops the indentation and yields the raw cell characters.
        self.grid = []
        for line in board.strip().splitlines():
            cells = line.split()
            if cells:
                self.grid.append(cells)
        self.rows = len(self.grid)
        self.cols = len(self.grid[0]) if self.grid else 0

    def get_winner(self):
        if self.rows == 0:
            return ""
        # Player X plays from left to right.
        if self._connects("X", lambda r, c: c == 0, lambda r, c: c == self.cols - 1):
            return "X"
        # Player O plays from top to bottom.
        if self._connects("O", lambda r, c: r == 0, lambda r, c: r == self.rows - 1):
            return "O"
        return ""

    def _connects(self, player, start_edge, end_edge):
        """Return True if `player` has a connected path from start_edge to end_edge."""
        visited = set()
        queue = deque()
        for r in range(self.rows):
            for c in range(self.cols):
                if self.grid[r][c] == player and start_edge(r, c):
                    queue.append((r, c))
                    visited.add((r, c))
        while queue:
            r, c = queue.popleft()
            if end_edge(r, c):
                return True
            for nr, nc in self._neighbors(r, c):
                if 0 <= nr < self.rows and 0 <= nc < self.cols:
                    if (nr, nc) not in visited and self.grid[nr][nc] == player:
                        visited.add((nr, nc))
                        queue.append((nr, nc))
        return False

    @staticmethod
    def _neighbors(r, c):
        # Hex (rhombus) adjacency: map (r, c) to axial (q, r) = (c, r).
        return (
            (r, c - 1), (r, c + 1),      # same row, left / right
            (r - 1, c), (r - 1, c + 1),  # row above
            (r + 1, c - 1), (r + 1, c),  # row below
        )
